import { ref, watch } from 'vue'

export function useDocumentSearch(keyword) {
  const results = ref([])
  const loading = ref(false)
  watch(keyword, async (value) => {
    loading.value = true
    const response = await fetch('/api/docs?q=' + encodeURIComponent(value))
    results.value = await response.json()
    loading.value = false
  })
  return { results, loading }
}
```

