import { defineStore } from 'pinia'
import { ref } from 'vue'

export const useDocStore = defineStore('docs', () => {
  const items = ref([])
  async function load() {
    const response = await fetch('/api/docs')
    items.value = await response.json()
  }
  return { items, load }
})
